mapper.select:
select sw.sign_word_name
from (
    select tsd.sign_word_id, max(tsd.answer_date) as last_date
    from test_session_detail tsd
    join test_session ts on tsd.test_session_id = ts.test_session_id
    where ts.member_id = #{memberId}
    group by tsd.sign_word_id
    order by last_date desc
    limit #{limit}
) recent
join sign_word sw on sw.sign_word_id = recent.sign_word_id
order by recent.last_date desc
